-- Local disposable fixtures only; all test objects/data roll back.
begin;
create schema m72_test;
create function m72_test.ok(value boolean,label text) returns void language plpgsql security invoker as $$begin if value is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function m72_test.denied(statement text,label text) returns void language plpgsql security invoker as $$begin begin execute statement;exception when insufficient_privilege then raise notice 'PASS %',label;return;end;raise exception 'FAIL % unexpectedly permitted',label;end$$;
grant usage on schema m72_test to castly_api,castly_engagement_worker,authenticated;
grant execute on all functions in schema m72_test to castly_api,castly_engagement_worker,authenticated;
select m72_test.ok((select count(*)=7 and bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='admin_private' and c.relname in('user_directory','talent_summaries','verification_summaries','badge_summaries','booking_summaries','grant_summaries','user_history')),'all seven user read models/history use RLS');
select m72_test.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'admin_project_%' and p.prosecdef),'projection maintenance is SECURITY INVOKER');
select m72_test.ok((select count(*)=8 from pg_indexes where schemaname='admin_private' and indexname in('admin_directory_role_created','admin_directory_created','admin_directory_prefix','admin_verification_state','admin_bookings_client','admin_bookings_talent','admin_grants_user','admin_history_user')),'operational lookups have purpose indexes');
insert into auth.users(id) values('72000000-0000-0000-0000-000000000001'),('72000000-0000-0000-0000-000000000002'),('72000000-0000-0000-0000-000000000003');
set local castly.admin_bootstrap_reviewed='M7.1-owner-approved';
insert into admin_private.principals(user_id,roles,state) values('72000000-0000-0000-0000-000000000001',array['SUPER_ADMIN'],'active');
select set_config('request.jwt.claim.sub','72000000-0000-0000-0000-000000000003',true);
set local role castly_api;
select m72_test.ok((select count(*)=0 from admin_private.user_directory),'ordinary user cannot enumerate operational directory');
select m72_test.ok((select count(*)=0 from admin_private.user_history),'ordinary user cannot read operational history');
select m72_test.denied($q$insert into admin_private.user_directory(user_id,display_name,created_at,updated_at) values(gen_random_uuid(),'forged',now(),now())$q$,'ordinary user cannot forge a projection');
select m72_test.denied($q$delete from admin_private.user_history$q$,'account history cannot be deleted');
select m72_test.denied($q$update admin_private.user_history set action='account.updated'$q$,'account history cannot be rewritten');
update public.users set display_name='M72 source update' where id='72000000-0000-0000-0000-000000000003';
reset role;
select m72_test.ok((select display_name='M72 source update' from admin_private.user_directory where user_id='72000000-0000-0000-0000-000000000003'),'legitimate source update projects atomically');
select m72_test.ok(exists(select 1 from admin_private.user_history where user_id='72000000-0000-0000-0000-000000000003' and action='account.updated'),'source update appends immutable history');
set local role castly_engagement_worker;
select m72_test.denied($q$select * from admin_private.user_directory$q$,'worker cannot read admin user directory');
reset role;
set local role authenticated;
select m72_test.denied($q$select * from admin_private.user_directory$q$,'mobile cannot read admin user directory');
reset role;
select set_config('request.jwt.claim.sub','72000000-0000-0000-0000-000000000001',true);
select set_config('request.admin.aal2','true',true),set_config('request.admin.mfa_at',now()::text,true),set_config('request.admin.auth_session','72000000-0000-0000-0000-000000000099',true),set_config('request.admin.reason','M72 local SQL security test',true);
set local role castly_api;
insert into admin_private.sessions(user_id,auth_session_id,principal_version,ip_fingerprint,agent_family) values(private.request_user_id(),'72000000-0000-0000-0000-000000000099',1,'fixture','other') returning id as session_id \gset
select set_config('request.admin.session',:'session_id',true);
select m72_test.ok((select count(*)=3 from admin_private.user_directory where user_id::text like '72000000-%'),'valid administrator sees minimized operational metadata');
select m72_test.ok((select count(*)=0 from public.users where id='72000000-0000-0000-0000-000000000003'),'admin directory does not widen private source-account RLS');
with changed as(update admin_private.user_directory set display_name='forged' where user_id='72000000-0000-0000-0000-000000000003' returning user_id)select m72_test.ok((select count(*)=0 from changed),'even administrator cannot directly modify source projections');
select m72_test.denied($q$insert into admin_private.user_history(user_id,actor_id,action) values(private.request_user_id(),private.request_user_id(),'account.updated')$q$,'administrator cannot fabricate account history');
select set_config('request.admin.session','',true);
select m72_test.ok((select count(*)=0 from admin_private.user_directory),'missing session removes all operational access');
reset role;
rollback;
